base = [[4]*13 for _ in range(20)]
markers=[(1,2),(1,9),(6,11),(7,4),(12,2),(13,11),(17,4),(17,8)]
# Source motif, centered at (12,7); 4 is transparent background.
pat=[[4,5,5],[8,5,8],[8,5,0]]
for r,c in markers:
    for dr in range(-1,2):
        for dc in range(-1,2):
            v=pat[dr+1][dc+1]
            if v != 4:
                base[r+dr][c+dc]=v
# The exemplar motif itself remains intact.
for dr in range(-1,2):
    for dc in range(-1,2):
        v=pat[dr+1][dc+1]
        if v != 4: base[12+dr][7+dc]=v
print(base)
print(len(base), set(map(len,base)))
